"""Pixel Wanderer — Streamlit browser-canvas roguelite.
Run: streamlit run app.py
Images supplied by the user are embedded; no external asset hosting required.
Keyboard focus: click the game once. Progress is session-local, not saved.
"""
import streamlit as st
import streamlit.components.v1 as components
st.set_page_config(page_title="도트 원더러", page_icon="⚔️", layout="wide")
st.title("⚔️ 도트 원더러")
st.caption("게임 화면을 한 번 클릭하세요 · A/D 이동 · W 점프 · S 플랫폼 내려가기 · Space 상호작용 · Q 돌진 · J 공격 · B 배낭 · R 재시작")
components.html('<!doctype html><html lang="ko"><meta charset="utf-8"><style>*{box-sizing:border-box}body{margin:0;background:#161b20;color:#efdfbf;font-family:system-ui}#wrap{position:relative;max-width:1200px;margin:auto}canvas{width:100%;display:block;outline:none;border:2px solid #806b45;border-radius:10px;image-rendering:pixelated}#tips{padding:10px;font-size:14px;color:#cbbd9d}button{background:#60452b;color:#fff0cc;border:1px solid #b79252;border-radius:6px;padding:7px 16px;cursor:pointer}#error{color:#ff9b85}</style><div id="wrap"><canvas id="game" width="1200" height="690" tabindex="0" aria-label="도트 로그라이크 게임. 클릭 후 키보드로 조작"></canvas><div id="tips">화면 클릭으로 시작 · B 배낭 · W 점프 · S 아래로 · J 공격 · Q 돌진 (1.5초) <button id="focus">게임 포커스</button><span id="error"></span></div></div><script>\n\'use strict\';\nconst RAW={"walk":["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"],"jump":["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"],"dash":["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"],"attack":["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"],"background":"data:image/png;base64,","bag":"data:image/png;base64,","hud":"data:image/png;base64,"}, c=document.getElementById(\'game\'),g=c.getContext(\'2d\');g.imageSmoothingEnabled=false;\nlet imgs={},keys={},ready=false,focused=false,bag=false,dead=false,mode=\'village\',floor=0,clock=0,last=0,spawnId=0;\nlet bagPage=0; let p,foes=[],drops=[],platforms=[],particles=[],inventory=[],toast=\'\',toastUntil=0,attackHits=new Set();\nconst W=1200,H=690,GROUND=481;\nfunction msg(s){toast=s;toastUntil=clock+3}\nfunction reset(){p={x:210,y:GROUND,vx:0,vy:0,dir:1,hp:100,maxhp:100,mp:50,maxmp:50,exp:0,need:100,lv:1,gold:0,power:18,ground:true,dash:0,dashCD:0,attack:0,attackCD:0,inv:0,drop:0};mode=\'village\';floor=0;foes=[];drops=[];platforms=[];inventory=[];particles=[];bag=false;dead=false;msg(\'어서 오세요! 오른쪽 문에서 Space로 원정을 시작하세요.\');}\nfunction enter(){floor++;mode=\'dungeon\';p.x=90;p.y=GROUND;p.vy=0;p.ground=true;foes=[];drops=[];platforms=[{x:250+Math.random()*70,y:GROUND-117,w:190},{x:610+Math.random()*55,y:GROUND-202,w:190},{x:870,y:GROUND-102,w:160}];for(let i=0;i<Math.min(3+floor,12);i++){foes.push({id:++spawnId,x:420+Math.random()*620,y:GROUND,hp:40+floor*14,max:40+floor*14,hit:0,cd:Math.random(),color:Math.random()>.5?\'#78984c\':\'#9667b2\'});}msg(floor+\'층 · 적을 모두 처치하면 오른쪽 문이 열립니다.\');}\nfunction level(exp){p.exp+=exp;while(p.exp>=p.need){p.exp-=p.need;p.lv++;p.need=Math.round(p.need*1.35);p.maxhp+=20;p.hp=p.maxhp;p.maxmp+=5;p.mp=p.maxmp;p.power+=4;msg(\'LEVEL UP! Lv \'+p.lv+\' · 체력/마나 회복\');}}\nfunction dropItem(x,y,type){drops.push({x,y,type,phase:Math.random()*6})}\nfunction interact(){if(dead||bag)return;let d=drops.find(a=>Math.abs(a.x-p.x)<65&&Math.abs(a.y-p.y)<85);if(d){if(d.type===\'gold\'){p.gold+=5+floor*2;msg(\'골드 획득\');}else if(d.type===\'charm\'){p.power+=3;msg(\'힘의 부적 · 공격력 +3\');}else{if(inventory.length>=80){msg(\'배낭이 가득 찼습니다.\');return;}inventory.push(d.type);msg((d.type===\'hp\'?\'체력\':\'마나\')+\' 물약 획득 · B로 사용\');}drops.splice(drops.indexOf(d),1);return;}if(mode===\'village\'){if(Math.abs(p.x-710)<65){if(p.gold>=10){p.gold-=10;p.hp=p.maxhp;p.mp=p.maxmp;msg(\'회복했습니다.\');}else msg(\'치유사: 회복은 10골드입니다. 원정으로 골드를 모으세요.\');}else if(p.x>1060)enter();else msg(\'오른쪽 원정 문으로 이동하세요.\');}else if(p.x>1060){if(foes.length===0)enter();else msg(\'남은 적을 먼저 처치하세요!\');}}\nfunction action(k){if(k===\'r\'&&dead){reset();return;}if(dead)return;if(k===\'b\'){bag=!bag;bagPage=0;keys={};return;}if(bag)return;if(k===\' \'){interact();return;}if(k===\'w\'&&p.ground){p.vy=-575;p.ground=false;}if(k===\'s\'){p.drop=.22;if(p.y<GROUND-5){p.y+=7;p.ground=false;p.vy=Math.max(100,p.vy);}}if(k===\'q\'&&p.dashCD<=0){p.dash=.19;p.dashCD=1.5;p.inv=Math.max(p.inv,.24);}if(k===\'j\'&&p.attackCD<=0){p.attack=.34;p.attackCD=.42;attackHits.clear();}}\nc.addEventListener(\'keydown\',e=>{let k=e.key.toLowerCase();if([\' \',\'w\',\'a\',\'s\',\'d\',\'q\',\'b\',\'j\',\'r\',\'arrowup\',\'arrowdown\'].includes(k))e.preventDefault();if(!e.repeat)action(k);keys[k]=true;});c.addEventListener(\'keyup\',e=>{keys[e.key.toLowerCase()]=false;});c.addEventListener(\'focus\',()=>{focused=true;});c.addEventListener(\'blur\',()=>{focused=false;keys={};});window.addEventListener(\'blur\',()=>{keys={};focused=false;});document.getElementById(\'focus\').onclick=()=>c.focus();\nconst BAG={x:650,y:95,w:530,h:530*764/1024};\nfunction bagPoint(x,y){return {x:(x-BAG.x)/BAG.w*1024,y:(y-BAG.y)/BAG.h*764};}\nc.addEventListener(\'click\',e=>{c.focus();if(!bag||dead)return;const r=c.getBoundingClientRect(),x=(e.clientX-r.left)*W/r.width,y=(e.clientY-r.top)*H/r.height;\nlet q=bagPoint(x,y);if(q.x>914&&q.x<975&&q.y>15&&q.y<80){bag=false;return;}\nif(x>1000&&x<1180&&y>510&&y<545&&inventory.length>72){bagPage=1-bagPage;return;}\nlet col=Math.floor((q.x-400)/60),row=Math.floor((q.y-148)/60);if(col>=0&&col<9&&row>=0&&row<8)use(bagPage*72+row*9+col);\n});\nfunction use(i){if(i>=inventory.length)return;let type=inventory[i];if(type===\'hp\'){if(p.hp>=p.maxhp){msg(\'이미 체력이 가득 찼습니다.\');return;}p.hp=Math.min(p.maxhp,p.hp+55);}else{if(p.mp>=p.maxmp){msg(\'이미 마나가 가득 찼습니다.\');return;}p.mp=Math.min(p.maxmp,p.mp+30);}inventory.splice(i,1);msg(\'물약을 사용했습니다.\');}\nfunction tick(dt){clock+=dt;if(!ready||!focused||bag||dead)return;for(let k of [\'dash\',\'dashCD\',\'attack\',\'attackCD\',\'inv\',\'drop\'])p[k]=Math.max(0,p[k]-dt);p.mp=Math.min(p.maxmp,p.mp+dt*2);let move=(keys.d?1:0)-(keys.a?1:0);if(move&&p.dash<=0)p.dir=move;p.vx=p.dash>0?p.dir*980:move*245;let prev=p.y;p.x=Math.max(25,Math.min(1170,p.x+p.vx*dt));p.vy+=1450*dt;p.y+=p.vy*dt;p.ground=false;let ground=GROUND;if(p.drop<=0&&p.vy>=0)for(let a of platforms)if(p.x>a.x-12&&p.x<a.x+a.w+12&&prev<=a.y+2&&p.y>=a.y)ground=Math.min(ground,a.y);if(p.y>=ground&&p.vy>=0){p.y=ground;p.vy=0;p.ground=true;}\nfor(let f of foes){f.hit=Math.max(0,f.hit-dt);f.cd-=dt;const dx=p.x-f.x;if(Math.abs(dx)>32)f.x+=Math.sign(dx)*(42+Math.min(floor,15)*5)*dt;if(p.attack>0&&Math.abs(dx)<108&&Math.abs(f.y-p.y)<85&&dx*p.dir<25&&!attackHits.has(f.id)){attackHits.add(f.id);f.hp-=p.power;f.hit=.17;f.x=Math.max(35,Math.min(1150,f.x+p.dir*22));particles.push({x:f.x,y:f.y-45,text:\'−\'+p.power,t:.65});}if(Math.abs(p.x-f.x)<38&&Math.abs(p.y-f.y)<52&&f.cd<=0&&p.inv<=0){p.hp-=8+floor*2;p.inv=.7;f.cd=1;particles.push({x:p.x,y:p.y-70,text:\'피격\',t:.65});if(p.hp<=0){p.hp=0;dead=true;keys={};}}}\nlet killed=foes.filter(f=>f.hp<=0);foes=foes.filter(f=>f.hp>0);for(let f of killed){level(28+floor*8);dropItem(f.x,GROUND,\'gold\');if(Math.random()<.6)dropItem(f.x+25,GROUND,Math.random()<.7?\'hp\':\'mp\');if(Math.random()<.12)dropItem(f.x-20,GROUND,\'charm\');if(foes.length===0)msg(\'층 클리어! 전리품을 줍고 오른쪽 문으로 이동하세요.\');}particles.forEach(a=>{a.t-=dt;a.y-=dt*30});particles=particles.filter(a=>a.t>0);}\nfunction text(s,x,y,size=18,color=\'#fff0d0\',align=\'left\'){g.font=\'bold \'+size+\'px system-ui\';g.textAlign=align;g.fillStyle=\'#16120f\';g.fillText(s,x+1,y+2);g.fillStyle=color;g.fillText(s,x,y);g.textAlign=\'left\';}\nfunction rect(x,y,w,h,color){g.fillStyle=color;g.fillRect(x,y,w,h)}\nfunction player(){let seq=\'walk\',i=0;if(p.dash>0){seq=\'dash\';i=Math.min(3,Math.floor((.19-p.dash)/.19*4));}else if(p.attack>0){seq=\'attack\';i=Math.min(3,Math.floor((.34-p.attack)/.34*4));}else if(!p.ground){seq=\'jump\';i=p.vy< -200?1:p.vy<150?2:3;}else if(Math.abs(p.vx)>0)i=Math.floor(clock*9)%4;let im=imgs[seq][i],height=seq===\'attack\'?108:88,width=im.width/im.height*height;if(p.inv>0&&Math.floor(clock*22)%2===0)g.globalAlpha=.45;g.save();g.translate(p.x,p.y);g.scale(p.dir,1);g.drawImage(im,-width/2,-height,width,height);g.restore();g.globalAlpha=1;}\nfunction hud(){g.drawImage(imgs.hud,15,15,472,112);rect(45,47,47,55,\'#513722\');text(\'Lv\',70,61,14,undefined,\'center\');text(\'\'+p.lv,70,94,29,undefined,\'center\');let rows=[[p.hp,p.maxhp,\'#c83448\'],[p.mp,p.maxmp,\'#347bd8\'],[p.exp,p.need,\'#cb9137\']];rows.forEach((r,i)=>{let y=29+i*34;rect(195,y,267,22,\'#30251e\');rect(197,y+2,263*Math.max(0,r[0]/r[1]),18,r[2]);text(Math.ceil(r[0])+\' / \'+r[1],330,y+17,14,\'#fff\',\'center\');});text((mode===\'village\'?\'안식의 마을\':floor+\'층 · 남은 적 \'+foes.length)+\'  |  골드 \'+p.gold+\'  |  ATK \'+p.power,20,154,16);let ratio=1-p.dashCD/1.5;rect(20,169,130,10,\'#302a23\');rect(20,169,130*ratio,10,\'#76c7b3\');text(p.dashCD>0?\'Q  \'+p.dashCD.toFixed(1)+\'초\':\'Q 돌진 준비\',160,180,14);}\nfunction inventoryUI(){\nrect(0,0,W,H,\'rgba(0,0,0,.45)\');g.drawImage(imgs.bag,BAG.x,BAG.y,BAG.w,BAG.h);\n// Preserve the supplied equipment artwork, character preview, slots and tabs.\n// Only the changing count, gold amount and item icons are drawn on top.\nfunction bx(x){return BAG.x+x/1024*BAG.w}function by(y){return BAG.y+y/764*BAG.h}\nrect(bx(711),by(31),94/1024*BAG.w,38/764*BAG.h,\'#ddc499\');text(\'\'+inventory.length,bx(757),by(60),16,\'#332519\',\'center\');\nrect(bx(493),by(661),127/1024*BAG.w,40/764*BAG.h,\'#684c30\');text(\'\'+p.gold,bx(536),by(691),16,\'#ffe3a1\',\'center\');\nfor(let slot=0;slot<72;slot++){let i=bagPage*72+slot;if(i>=inventory.length)break;let x=bx(430+slot%9*60),y=by(178+Math.floor(slot/9)*60);text(inventory[i]===\'hp\'?\'♥\':\'◆\',x,y+7,22,inventory[i]===\'hp\'?\'#ee6067\':\'#6bafff\',\'center\');}\ntext(\'물약 클릭: 사용 · B: 닫기\',917,520,16,undefined,\'center\');if(inventory.length>72)text(\'페이지 \'+(bagPage+1)+\'/2 ▶\',1095,540,14,\'#ffe4a2\',\'center\');\n}\nfunction draw(){rect(0,0,W,H,\'#18222a\');if(!ready){text(\'이미지 불러오는 중…\',600,340,24,undefined,\'center\');return;}g.drawImage(imgs.background,0,0,W,670);if(mode===\'dungeon\'){rect(0,0,W,GROUND,\'rgba(12,19,38,.57)\');for(let i=0;i<18;i++){let x=i*85;rect(x,GROUND-27,45,27,\'#35453d\');rect(x+7,GROUND-21,30,6,\'#5a6455\');}for(let a of platforms){rect(a.x,a.y,a.w,16,\'#344537\');rect(a.x,a.y,a.w,5,\'#89945a\');}}// Original grass and underground remain untouched; GROUND is aligned to the grass surface.\n\nif(mode===\'village\'){text(\'치유사\',710,GROUND-102,16,undefined,\'center\');text(\'✚\',710,GROUND-64,30,\'#a2e4b5\',\'center\');text(\'Space · 회복 10G\',710,GROUND-37,13,undefined,\'center\');}let unlocked=mode===\'village\'||foes.length===0;rect(1105,GROUND-102,60,102,unlocked?\'#35666a\':\'#3b343d\');rect(1115,GROUND-92,40,90,unlocked?\'#75bdba\':\'#514652\');text(unlocked?(mode===\'village\'?\'원정 시작\':\'다음 층\'):\'잠김\',1135,GROUND-120,17,undefined,\'center\');text(\'Space\',1135,GROUND+24,13,undefined,\'center\');\nfor(let d of drops){let y=d.y-15+Math.sin(clock*4+d.phase)*4;text(d.type===\'gold\'?\'●\':d.type===\'charm\'?\'★\':d.type===\'hp\'?\'♥\':\'◆\',d.x,y,23,{gold:\'#ffcc4f\',charm:\'#e3aaff\',hp:\'#f06a78\',mp:\'#7bc6ff\'}[d.type],\'center\');}\nfor(let f of foes){g.fillStyle=f.hit>0?\'#fff\':f.color;g.beginPath();g.ellipse(f.x,f.y-17,25,20,0,Math.PI,Math.PI*2);g.lineTo(f.x+25,f.y);g.lineTo(f.x-25,f.y);g.fill();rect(f.x-12,f.y-20,5,6,\'#171820\');rect(f.x+8,f.y-20,5,6,\'#171820\');rect(f.x-25,f.y-38,50,5,\'#291d25\');rect(f.x-25,f.y-38,50*f.hp/f.max,5,\'#cc6d6f\');}player();particles.forEach(a=>text(a.text,a.x,a.y,20,\'#ffe0a0\',\'center\'));hud();text(\'A / D 이동   W 점프   S 내려가기   J 공격   Space 상호작용   B 배낭\',600,643,17,\'#d7c59f\',\'center\');let near=drops.some(a=>Math.abs(a.x-p.x)<65&&Math.abs(a.y-p.y)<85);if(near)text(\'Space · 아이템 줍기\',p.x,p.y-110,15,\'#ffe08a\',\'center\');if(clock<toastUntil){rect(230,590,740,32,\'rgba(18,16,15,.88)\');text(toast,600,612,16,undefined,\'center\');}if(bag)inventoryUI();if(!focused&&!dead){rect(0,0,W,H,\'rgba(0,0,0,.46)\');text(\'화면을 클릭하여 시작 / 계속하기\',600,310,28,undefined,\'center\');text(\'키보드 포커스가 없으면 자동 일시정지\',600,349,17,undefined,\'center\');}if(dead){rect(0,0,W,H,\'rgba(13,8,12,.82)\');text(\'원정 종료\',600,280,40,\'#eaa78c\',\'center\');text(floor+\'층 · Lv \'+p.lv+\' · 골드 \'+p.gold,600,327,22,undefined,\'center\');text(\'R 키로 새 원정 시작\',600,380,23,undefined,\'center\');}}\nfunction loop(t){const dt=Math.min((t-last)/1000||0,.035);last=t;tick(dt);draw();requestAnimationFrame(loop)}\nfunction load(src){return new Promise((resolve,reject)=>{let im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error(\'내장 이미지 로딩 실패\'));im.src=src;});}\nPromise.all(Object.entries(RAW).map(async([k,v])=>{imgs[k]=Array.isArray(v)?await Promise.all(v.map(load)):await load(v)})).then(()=>{ready=true;reset();}).catch(e=>{document.getElementById(\'error\').textContent=e.message;});requestAnimationFrame(loop);\n</script></html>', height=790, scrolling=False)
with st.expander("게임 안내 / GitHub 배포"):
    st.markdown("""**목표:** 마을 오른쪽 문에서 원정 시작 → 적 처치 → 전리품 획득 → 다음 층 진입. 사망하면 새 원정으로 시작합니다.

- **Space:** 근처 아이템 줍기, NPC 회복(10골드), 원정 문/다음 층 이용. 화면 안내를 확인하세요.
- **S:** 공중 플랫폼을 통과해 아래로 내려갑니다. 지면 아래로는 내려갈 수 없습니다.
- **Q:** 바라보는 방향으로 돌진. 재사용 1.5초, 돌진 중 무적.
- **J:** 기본 근접 공격. **B:** 오른쪽 배낭 열기/닫기. 물약을 클릭하면 사용합니다.
- 가방은 80칸이며 물약은 개별 슬롯을 사용합니다. 부적은 획득 즉시 공격력을 올립니다.
- 배낭을 열거나 게임이 포커스를 잃으면 전투가 일시정지됩니다.
- 적/플랫폼/보상은 층마다 무작위로 생성됩니다. **R**은 사망했을 때 재시작합니다.
- 진행은 현재 게임 화면에서만 유지됩니다. 새로고침/앱 재실행 시 초기화됩니다.

**배포:** GitHub 저장소 루트에 `app.py`와 `requirements.txt`를 올리고 Streamlit Community Cloud에서 저장소와 `app.py`를 선택하세요. 로컬에서는 `pip install -r requirements.txt` 후 `streamlit run app.py`를 실행하세요.

**구현:** Python이 Streamlit 화면을 제공하고, 브라우저 Canvas가 실시간 입력·물리·렌더링을 처리합니다. 이미지 7종을 내장하므로 추가 파일은 필요하지 않습니다. 데스크톱 키보드 기준입니다.
""")
